{"command":"cat > src/bartib.py << 'PYEOF'
#!/usr/bin/env python3
import os
import sys
import time
import re
import math
import unicodedata
import subprocess

VERSION = "1.1.0"
NBSP = "\u00a0"

# ---------- output helpers ----------
def out(s=""):
    data = s.encode("utf-8", "surrogateescape")
    try:
        sys.stdout.buffer.write(data)
        sys.stdout.buffer.flush()
    except BrokenPipeError:
        # Avoid a second error at interpreter shutdown.
        try:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, sys.stdout.fileno())
        except Exception:
            pass
        raise SystemExit(1)

def err_out(s=""):
    data = s.encode("utf-8", "surrogateescape")
    try:
        sys.stderr.buffer.write(data)
        sys.stderr.buffer.flush()
    except BrokenPipeError:
        raise SystemExit(1)

def style(code, text):
    return f"\x1b[{code}m{text}\x1b[0m"
def bold(t): return style("1", t)
def dim(t): return style("2", t)
def italic(t): return style("3", t)
def underline(t): return style("4", t)
def green(t): return style("32", t)
def yellow(t): return style("33", t)
def bold_green(t): return style("1;32", t)
def dim_italic(t): return style("2;3", t)

RUST_WS = "\t\n\x0b\x0c\r \x85\xa0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000"
def rust_trim(s):
    return s.strip(RUST_WS)

def io_error_str(e):
    if getattr(e, "errno", None) is not None:
        return f"{os.strerror(e.errno)} (os error {e.errno})"
    return str(e)

class AppError(Exception):
    def __init__(self, msg, cause=None):
        super().__init__(msg)
        self.msg = msg
        self.cause = cause
    def render(self):
        if self.cause is not None:
            return f"Error: {self.msg}\n\nCaused by:\n    {self.cause}\n"
        return f"Error: {self.msg}\n"

class RustPanic(Exception):
    def __init__(self, location, msg):
        super().__init__(msg)
        self.location = location
        self.msg = msg

class ExitCode(Exception):
    def __init__(self, code):
        self.code = code

# ---------- date/time ----------
def is_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
def days_in_month(y, m):
    if m == 2:
        return 29 if is_leap(y) else 28
    return [31,28,31,30,31,30,31,31,30,31,30,31][m-1]
def days_from_civil(y, m, d):
    yy = y - (1 if m <= 2 else 0)
    era = (yy if yy >= 0 else yy - 399) // 400
    yoe = yy - era * 400
    mp = (m + 9) % 12
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468
def civil_from_days(z):
    zz = z + 719468
    era = (zz if zz >= 0 else zz - 146096) // 146097
    doe = zz - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    y = yoe + era * 400
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    d = doy - (153 * mp + 2) // 5 + 1
    m = mp + 3 if mp < 10 else mp - 9
    y += 1 if m <= 2 else 0
    return (y, m, d)

class Date:
    __slots__=("y","m","d")
    def __init__(self,y,m,d): self.y=y; self.m=m; self.d=d
    def days(self): return days_from_civil(self.y,self.m,self.d)
    @staticmethod
    def from_days(z):
        y,m,d=civil_from_days(z); return Date(y,m,d)
    def add_days(self,n): return Date.from_days(self.days()+n)
    def weekday_mon0(self):
        # 1970-01-01 was Thursday; Monday=0 -> Thursday=3
        return (self.days()+3) % 7
    def __eq__(self,o): return isinstance(o,Date) and (self.y,self.m,self.d)==(o.y,o.m,o.d)
    def __lt__(self,o): return (self.y,self.m,self.d)<(o.y,o.m,o.d)
    def __le__(self,o): return (self.y,self.m,self.d)<=(o.y,o.m,o.d)
    def __hash__(self): return hash((self.y,self.m,self.d))
    def __repr__(self): return f"Date({self.y},{self.m},{self.d})"

class DateTime:
    __slots__=("y","m","d","hour","minute","second","nano")
    def __init__(self,y,m,d,hour,minute,second=0,nano=0):
        self.y=y; self.m=m; self.d=d; self.hour=hour; self.minute=minute; self.second=second; self.nano=nano
    def date(self): return Date(self.y,self.m,self.d)
    def fields(self): return (self.y,self.m,self.d,self.hour,self.minute,self.second,self.nano)
    def __eq__(self,o): return isinstance(o,DateTime) and self.fields()==o.fields()
    def __lt__(self,o): return self.fields()<o.fields()
    def __le__(self,o): return self.fields()<=o.fields()
    def __repr__(self): return f"DateTime{self.fields()}"
    def epoch_seconds(self):
        # Instant in seconds; second==60 (leap) advances to the next minute.
        return days_from_civil(self.y,self.m,self.d)*86400 + self.hour*3600 + self.minute*60 + self.second
    def epoch_nanos(self):
        return self.epoch_seconds()*1_000_000_000 + self.nano
    @staticmethod
    def from_epoch_seconds(sec, nano=0):
        days = sec // 86400 if sec>=0 or sec%86400==0 else sec//86400
        # Python // is floor division, already correct.
        days = sec // 86400
