            else:
                seg=content[pos:idx]; pos=idx+1; terminated=True
            if terminated and seg.endswith(b"\r"):
                seg=seg[:-1]
            try:
                text=seg.decode("utf-8")
            except UnicodeDecodeError:
                break
            decoded.append(text)
        segments=decoded
    lines=[]
    for idx, raw in enumerate(segments):
        text=rust_trim(raw)
        act=None; error=None
        try:
            act=parse_activity(text, idx+1, idx)
        except ActivityParseError as e:
            error=e.kind
        lines.append(Line(text, act, error, idx+1))
    return BartibFile(path, lines)

def print_warnings(bf):
    for ln in bf.lines:
        if ln.error is not None:
            out(f"Warning: Ignoring line {ln.line_number}. Please see `bartib check` for further information\n")

def get_activities(bf, warnings=True):
    if warnings:
        print_warnings(bf)
    return bf.activities()

# ---------- Unicode width / wrapping ----------
def char_width(c):
    if c=="":
        return 0
    o=ord(c)
    if o==0: return 0
    if o<32 or (0x7f<=o<0xa0): return 0
    if unicodedata.combining(c): return 0
    cat=unicodedata.category(c)
    if cat in ("Mn","Me","Cf"):
        # Some Cf (e.g. soft hyphen) have width 1 in unicode-width.
        if o==0x00ad: return 1
        return 0
    if o in (0x1160,0x11ff) or (0x3029<=o<=0x302e) or o in (0x3099,0x309a,0x27c2):
        return 0
    eaw=unicodedata.east_asian_width(c)
    if eaw in ("W","F"): return 2
    # A handful of emoji/symbols are wide in unicode-width although EAW is N.
    if o>=0x1f000: return 2
    return 1
def text_width(s):
    return sum(char_width(c) for c in s)

def _is_break_between(prev, nxt):
    if prev=="" or nxt=="": return False
    if unicodedata.combining(nxt) or unicodedata.category(nxt) in ("Mn","Me"): return False
    if prev=="-": return True
    if char_width(prev)==2 or char_width(nxt)==2: return True
    return False

class _Frag:
    __slots__=("text","space","width","space_width","artificial_end")
    def __init__(self,text,space=""):
        self.text=text; self.space=space
        self.width=text_width(text); self.space_width=text_width(space)
        self.artificial_end=False

def _tokenize_for_wrap(s, width):
    # Split into fragments at spaces / unicode break opportunities.
    frags=[]; i=0; n=len(s); start=0
    while i<n:
        # Decide fragment end: scan until a space run or break opportunity.
        j=i
        # A fragment starts at i; advance at least one char.
        j+=1
        while j<n:
            if s[j]==" ":
                break
            if _is_break_between(s[j-1], s[j]):
                break
            j+=1
        text=s[i:j]
        sp_start=j
        while j<n and s[j]==" ":
            j+=1
        space=s[sp_start:j]
        frags.append(_Frag(text,space))
        i=j
    # Split fragments that are themselves wider than width into
    # grapheme-ish pieces (char + following zero-width marks).
    out=[]
    for fr in frags:
        if width>0 and fr.width>width:
            pieces=[]; cur=""; curw=0
            for c in fr.text:
                cw=char_width(c)
                if cur and curw+cw>width and cw!=0:
                    pieces.append(cur); cur=c; curw=cw
                else:
                    cur+=c; curw+=cw
            if cur or not pieces: pieces.append(cur)
            for k,p in enumerate(pieces):
                nf=_Frag(p, fr.space if k==len(pieces)-1 else "")
                nf.artificial_end = (k != len(pieces)-1)
                out.append(nf)
        else:
            out.append(fr)
    return out

def wrap_text(s, width):
    """Approximation of the reference text wrapping (textwrap optimising
    line breaks).  Only triggered for display purposes."""
    if s=="":
        return [""]
    if width is None or width<=0:
        return [s]
    if text_width(s) <= width:
        return [s]
    frags=_tokenize_for_wrap(s,width)
    if not frags:
        return [s]
    n=len(frags)
    # Dynamic programming from the end. costs[i] = best cost wrapping frags[i:].
    INF=10**18
    costs=[INF]*(n+1); nxt=[n]*(n+1); costs[n]=0
    # prefix widths for quick line width computation
    for i in range(n-1,-1,-1):
        line_w=0; best=INF; best_j=None
        for j in range(i,n):
            if j>i:
                # add previous fragment's trailing space (it is internal now)
                line_w += frags[j-1].space_width
            line_w += frags[j].width
            is_last = (j==n-1)
            if line_w>width:
                # Allow a single fragment to overflow the line.
                if j==i:
                    overflow=line_w-width
                    cost=2500*overflow
                    if not is_last: cost+=1000
                    total=cost+costs[j+1]
                    if total<best:
                        best=total; best_j=j
                break
            if is_last:
                cost=0
                # Penalty for a very short last line (only if it is not
                # also the first line).
                if i!=0 and line_w*4 < width:
                    cost+=25
            else:
                gap=width-line_w
                cost=1000+gap*gap
                if frags[j].artificial_end:
                    cost+=25
                # Textwrap also penalises breaks at hyphens slightly;
                # that mostly matters for artificial splits above.
            total=cost+costs[j+1]
            if total<best:
                best=total; best_j=j
        costs[i]=best; nxt[i]=(best_j if best_j is not None else i)
    lines=[]; i=0
    while i<n:
        j=nxt[i]
        parts=[]
        for k in range(i,j+1):
            parts.append(frags[k].text)
            if k<j:
                parts.append(frags[k].space)
        lines.append("".join(parts))
        i=j+1
    return lines

# ---------- table rendering ----------
def render_table(header, rows, row_styles=None):
    """Rows are lists of cell strings. Returns the table body (header +
    rows) without the leading/trailing blank lines."""
    cols=len(header)
    widths=[]
    for c in range(cols):
        w=len(header[c])
        for r in rows:
            if len(r[c])>w: w=len(r[c])
        widths.append(w)
    def fmt_row(cells, style_fn, is_header=False):
        wrapped=[wrap_text(cells[c], widths[c]) for c in range(cols)]
        height=max((len(x) for x in wrapped), default=1)
        buf=[]
        for h in range(height):
            for c in range(cols):
                seg=wrapped[c][h] if h<len(wrapped[c]) else ""
                pad=NBSP*max(0,widths[c]-len(seg))
                text=seg+pad
                if style_fn is not None:
                    text=style_fn(text)
                buf.append(text+" ")
            buf.append("\n")
        return "".join(buf)
    out_s=fmt_row(header, underline, True)
    for idx,r in enumerate(rows):
        sf=None
        if row_styles is not None:
            st=row_styles[idx]
            if st=="green": sf=green
            elif st=="yellow": sf=yellow
        out_s+=fmt_row(r, sf)
    return out_s

def print_table(header, rows, row_styles=None):
    out("\n")
    out(render_table(header,rows,row_styles))
    out("\n")

