def render_grouped_table(header, groups):
    cols=len(header); widths=[]
    all_rows=[]
    for _label, rows, _styles in groups: all_rows.extend(rows)
    for c in range(cols):
        w=len(header[c])
        for r in all_rows:
            if len(r[c])>w: w=len(r[c])
        widths.append(w)
    def fmt_row(cells, style_fn):
        wrapped=[wrap_text(cells[c], widths[c]) for c in range(cols)]
        height=max((len(x) for x in wrapped), default=1); buf=[]
        for h in range(height):
            for c in range(cols):
                seg=wrapped[c][h] if h<len(wrapped[c]) else ""
                text=seg+NBSP*max(0,widths[c]-len(seg))
                if style_fn is not None: text=style_fn(text)
                buf.append(text+" ")
            buf.append("\n")
