            if styles is not None:
                if styles[idx]=="green": sf=green
                elif styles[idx]=="yellow": sf=yellow
            s+=fmt_row(r,sf)
    return s

# ---------- filter ----------
class Filter:
    def __init__(self, project=None, date=None, from_date=None, to_date=None):
        self.project=project; self.date=date; self.from_date=from_date; self.to_date=to_date
    def matches(self, act):
        if self.project is not None and act.project!=self.project: return False
        d=act.start.date()
        if self.date is not None and d!=self.date: return False
        if self.from_date is not None and d<self.from_date: return False
        if self.to_date is not None and d>self.to_date: return False
        return True

def build_filter(vals):
    filt=Filter()
    # -d/--date
    if vals.get("date") is not None:
        filt.date=parse_date_arg(vals.get("date"), "-d/--date")
    today=None
    def get_today():
        nonlocal today
        if today is None: today=local_now().date()
        return today
    if vals.get("today"):
        filt.date=get_today()
    if vals.get("yesterday"):
        filt.date=get_today().add_days(-1)
    if vals.get("current_week"):
        t=get_today(); first=t.add_days(-t.weekday_mon0())
        filt.from_date=first; filt.to_date=first.add_days(6)
    if vals.get("last_week"):
        t=get_today(); first=t.add_days(-t.weekday_mon0()-7)
        filt.from_date=first; filt.to_date=first.add_days(6)
    if vals.get("from") is not None:
        filt.from_date=parse_date_arg(vals.get("from"), "--from")
    if vals.get("to") is not None:
        filt.to_date=parse_date_arg(vals.get("to"), "--to")
    if vals.get("project") is not None:
        filt.project=vals.get("project")
    return filt

def apply_round(activities, interval):
    if interval is None: return
    for a in activities:
        a.start=round_datetime(a.start, interval)
        if a.end is not None:
            a.end=round_datetime(a.end, interval)

def sorted_by_start(activities):
    return sorted(activities, key=lambda a: a.start.fields())

def distinct_recent(activities_sorted, limit=None):
    """Returns list of (index, activity) in recent-first order (index 0 =
    most recent distinct), truncated to limit if given (not None)."""
    seen=set(); res=[]
    for a in reversed(activities_sorted):
        key=(a.description,a.project)
        if key in seen: continue
        seen.add(key)
        res.append(a)
        if limit is not None and len(res)>=limit:
            break
    return list(enumerate(res))

# ---------- commands: mutation helpers ----------
def stop_all_activities(bf, stop_dt):
    for ln in bf.lines:
        a=ln.activity
        if a is not None and a.is_running():
            a.end=stop_dt
            ln.text=activity_to_line(a)
            out(f'Stopped activity: "{a.description}" ({a.project}) started at {format_datetime(a.start)} ({duration_str(a.duration_ns())})\n')

def start_activity_on_file(bf, start_dt, description, project):
    stop_all_activities(bf, start_dt)
    act=Activity(start_dt, None, project, description, len(bf.lines)+1, len(bf.lines))
    bf.lines.append(Line(activity_to_line(act), act, None, len(bf.lines)+1))
    out(f'Started activity: "{description}" ({project}) at {format_datetime(start_dt)}\n')

