def cmd_continue(path, vals):
    start_dt=get_datetime_from_time_arg(vals.get("time"))
    number=get_number_arg(vals.get("NUMBER"))
    if number is None: number=0
    bf=read_bartib_file(path)
    activities=get_activities(bf, warnings=True)
    if not activities:
        raise AppError("No activity has been started before.")
    srt=sorted_by_start(activities)
    distinct=distinct_recent(srt, limit=None)  # [(0,most recent),...]
    distinct_acts=[a for _i,a in distinct]
    if len(distinct_acts) < number:
        raise AppError(f"Less than {number} distinct activities have been logged yet")
    if number < len(distinct_acts):
        chosen=distinct_acts[number]
    else:
        chosen=distinct_acts[-1]
    desc=vals.get("description") if vals.get("description") is not None else chosen.description
    proj=vals.get("project") if vals.get("project") is not None else chosen.project
    start_activity_on_file(bf, start_dt, desc, proj)
    bf.save()

