        if a.duration_ns()<0:
            issues.append("Activity has negative duration")
        if max_end is not None and a.start.fields() < max_end.fields():
            issues.append("Activity started before another activity ended")
        if issues:
            reports.append((a,issues))
        if a.end is not None:
            if max_end is None or a.end.fields()>max_end.fields():
                max_end=a.end
    if not reports:
        out("No unusual activities.\n"); return
    for a,issues in reports:
        for m in issues: out(m+"\n")
        ended=format_datetime(a.end) if a.end is not None else "--"
        out(f"{a.description} (Started: {format_datetime(a.start)}, Ended: {ended}, Line: {a.line_number})\n")
