def _wildmatch(pattern, text):
    # Standard wildcard matching with * and ? over codepoints.
    p=t=0; star_p=-1; star_t=0
    lp=len(pattern); lt=len(text)
    while t<lt:
        if p<lp and (pattern[p]=="?" or pattern[p]==text[t]):
            p+=1; t+=1
        elif p<lp and pattern[p]=="*":
            star_p=p; star_t=t; p+=1
        elif star_p!=-1:
            p=star_p+1; star_t+=1; t=star_t
        else:
            return False
    while p<lp and pattern[p]=="*": p+=1
    return p==lp

def cmd_search(path, vals, term_present):
    bf=read_bartib_file(path)
    activities=get_activities(bf, warnings=True)
    if not term_present:
        out("No matching activities found\n"); return
    term=vals.get("SEARCH_TERM") or ""
    pattern=("*"+term+"*").lower()
    srt=sorted_by_start(activities)
    distinct=distinct_recent(srt, limit=None)
    matches=[]
    for idx,a in distinct:
        if _wildmatch(pattern, a.description.lower()) or _wildmatch(pattern, a.project.lower()):
            matches.append((idx,a))
    if not matches:
        out("No matching activities found\n"); return
    rows=[[f"[{idx}]", a.description, a.project] for idx,a in reversed(matches)]
    print_table([" #","Description","Project"], rows)

