    bf.lines.append(Line(activity_to_line(act), act, None, len(bf.lines)+1))
    out(f'Started activity: "{description}" ({project}) at {format_datetime(start_dt)}\n')

# ---------- commands ----------
def cmd_start(path, vals):
    start_dt=get_datetime_from_time_arg(vals.get("time"))
    bf=read_bartib_file(path, allow_missing=True)
    start_activity_on_file(bf, start_dt, vals.get("description"), vals.get("project"))
    bf.save()

def cmd_stop(path, vals):
    stop_dt=get_datetime_from_time_arg(vals.get("time"))
    bf=read_bartib_file(path)
    stop_all_activities(bf, stop_dt)
    bf.save()

def cmd_cancel(path, vals):
    bf=read_bartib_file(path)
    keep=[]
    for ln in bf.lines:
        a=ln.activity
        if a is not None and a.is_running():
            out(f'Canceled activity: "{a.description}" ({a.project}) started at {format_datetime(a.start)}\n')
        else:
            keep.append(ln)
    bf.lines=keep
    bf.save()

def cmd_change(path, vals):
    new_time=get_optional_datetime_from_time_arg(vals.get("time"))
    bf=read_bartib_file(path)
    desc=vals.get("description"); proj=vals.get("project")
    if desc is not None or proj is not None or new_time is not None:
        for ln in bf.lines:
            a=ln.activity
            if a is not None and a.is_running():
                if desc is not None: a.description=desc
                if proj is not None: a.project=proj
                if new_time is not None: a.start=new_time
                ln.text=activity_to_line(a)
                out(f'Changed activity: "{a.description}" ({a.project}) started at {format_datetime(a.start)}\n')
    bf.save()

def cmd_continue(path, vals):
    start_dt=get_datetime_from_time_arg(vals.get("time"))
    number=get_number_arg(vals.get("NUMBER"))
    if number is None: number=0
    bf=read_bartib_file(path)
    activities=get_activities(bf, warnings=True)
    if not activities:
        raise AppError("No activity has been started before.")
    srt=sorted_by_start(activities)
    distinct=distinct_recent(srt, limit=None)  # [(0,most recent),...]
    distinct_acts=[a for _i,a in distinct]
    if len(distinct_acts) < number:
        raise AppError(f"Less than {number} distinct activities have been logged yet")
    if number < len(distinct_acts):
        chosen=distinct_acts[number]
    else:
        chosen=distinct_acts[-1]
    desc=vals.get("description") if vals.get("description") is not None else chosen.description
    proj=vals.get("project") if vals.get("project") is not None else chosen.project
    start_activity_on_file(bf, start_dt, desc, proj)
    bf.save()

def cmd_current(path, vals):
    bf=read_bartib_file(path)
    activities=get_activities(bf, warnings=True)
    running=[a for a in activities if a.is_running()]
    if not running:
        out("No Activity is currently running\n"); return
    rows=[[format_datetime(a.start), a.description, a.project, duration_str(a.duration_ns())] for a in running]
    print_table(["Started At","Description","Project","Duration"], rows)

def _activity_row(a, full_start):
    started=format_datetime(a.start) if full_start else format_time(a.start)
    if a.end is None:
        stopped="-"; st="green"
    elif a.end.date()!=a.start.date():
        stopped=format_datetime(a.end); st="yellow"
    else:
        stopped=format_time(a.end); st=None
    return [started, stopped, a.description, a.project, duration_str(a.duration_ns())], st

def cmd_list(path, vals):
    number=get_number_arg(vals.get("number"))
    filt=build_filter(vals)
