        out("\n")
        out(render_grouped_table(header, groups))
        out("\n")

def cmd_report(path, vals):
    filt=build_filter(vals)
    interval=parse_duration_arg(vals.get("round"))
    bf=read_bartib_file(path)
    activities=get_activities(bf, warnings=True)
    apply_round(activities, interval)
    filtered=[a for a in activities if filt.matches(a)]
    # Group project -> description -> total ns
    proj_map={}
    for a in filtered:
        dur=a.duration_ns()
        dm=proj_map.setdefault(a.project,{})
        dm[a.description]=dm.get(a.description,0)+dur
    projects=sorted(proj_map.keys())
    # Precompute duration strings
    proj_totals={p: sum(proj_map[p].values()) for p in projects}
    dur_strs={}
    max_dur_len=0
    for p in projects:
        s=duration_str(proj_totals[p]); dur_strs[("p",p)]=s; max_dur_len=max(max_dur_len,len(s))
        for d in proj_map[p]:
            s=duration_str(proj_map[p][d]); dur_strs[("d",p,d)]=s; max_dur_len=max(max_dur_len,len(s))
    total_ns=sum(proj_totals.values())
    max_label=0
    for p in projects:
        max_label=max(max_label, len(p))
        for d in proj_map[p]:
            max_label=max(max_label, len(d)+4)
    def fmt_line(name, indent, dur_s, align=True):
        field=max_label-len(indent)
        if field<0: field=0
        wrapped=wrap_text(name, field) if field>0 else [name]
        lines=[]
        for seg in wrapped[:-1]:
            lines.append(indent+seg)
        last=wrapped[-1] if wrapped else ""
        dots="."*max(0, field-len(last))
        dur_disp=dur_s.rjust(max_dur_len) if align else dur_s
        lines.append(f"{indent}{last}{dots} {dur_disp}")
        return "\n".join(lines)
    out("\n")
    for p in projects:
        out(bold(fmt_line(p,"",dur_strs[("p",p)]))+"\n")
        for d in sorted(proj_map[p].keys()):
            out(fmt_line(d,"    ",dur_strs[("d",p,d)])+"\n")
        out("\n")
    total_dots="."*max(0, max_label-len("Total"))
    out(bold(f"Total{total_dots} {duration_str(total_ns)}")+"\n")
    out("\n")

def cmd_projects(path, vals):
    bf=read_bartib_file(path)
    activities=get_activities(bf, warnings=True)
    if vals.get("current"):
