def cmd_last(path, vals):
    number=get_number_arg(vals.get("number"))
    limit=number if number is not None else 10
    bf=read_bartib_file(path)
    activities=get_activities(bf, warnings=True)
    srt=sorted_by_start(activities)
    distinct=distinct_recent(srt, limit=limit)
    if not distinct:
        out("No activities have been tracked yet\n"); return
    rows=[]
    for idx,a in reversed(distinct):
        rows.append([f"[{idx}]", a.description, a.project])
    print_table([" #","Description","Project"], rows)

def _wildmatch(pattern, text):
    # Standard wildcard matching with * and ? over codepoints.
    p=t=0; star_p=-1; star_t=0
    lp=len(pattern); lt=len(text)
    while t<lt:
        if p<lp and (pattern[p]=="?" or pattern[p]==text[t]):
            p+=1; t+=1
        elif p<lp and pattern[p]=="*":
            star_p=p; star_t=t; p+=1
        elif star_p!=-1:
            p=star_p+1; star_t+=1; t=star_t
        else:
            return False
    while p<lp and pattern[p]=="*": p+=1
    return p==lp

def cmd_search(path, vals, term_present):
    bf=read_bartib_file(path)
    activities=get_activities(bf, warnings=True)
    if not term_present:
        out("No matching activities found\n"); return
    term=vals.get("SEARCH_TERM") or ""
    pattern=("*"+term+"*").lower()
    srt=sorted_by_start(activities)
    distinct=distinct_recent(srt, limit=None)
    matches=[]
    for idx,a in distinct:
        if _wildmatch(pattern, a.description.lower()) or _wildmatch(pattern, a.project.lower()):
            matches.append((idx,a))
    if not matches:
        out("No matching activities found\n"); return
    rows=[[f"[{idx}]", a.description, a.project] for idx,a in reversed(matches)]
    print_table([" #","Description","Project"], rows)

def cmd_check(path, vals):
    bf=read_bartib_file(path)
    errors=bf.errors()
    if not errors:
        out("All lines in the file have been successfully parsed as activities.\n"); return
    out(f"Found {len(errors)} line(s) with parsing errors\n")
    for ln in errors:
        out(f"\n{ln.text}\n  -> {ln.error} (Line: {ln.line_number})\n")

def cmd_sanity(path, vals):
    bf=read_bartib_file(path)
    activities=bf.activities()
    srt=sorted_by_start(activities)
    max_end=None; reports=[]
    for a in srt:
        issues=[]
        if a.duration_ns()<0:
            issues.append("Activity has negative duration")
        if max_end is not None and a.start.fields() < max_end.fields():
            issues.append("Activity started before another activity ended")
        if issues:
            reports.append((a,issues))
        if a.end is not None:
            if max_end is None or a.end.fields()>max_end.fields():
                max_end=a.end
    if not reports:
        out("No unusual activities.\n"); return
    for a,issues in reports:
        for m in issues: out(m+"\n")
        ended=format_datetime(a.end) if a.end is not None else "--"
        out(f"{a.description} (Started: {format_datetime(a.start)}, Ended: {ended}, Line: {a.line_number})\n")
        out("\n")

def cmd_status(path, vals):
    bf=read_bartib_file(path)
    activities=get_activities(bf, warnings=True)
    project=vals.get("project")
    today=local_now().date()
    week_first=today.add_days(-today.weekday_mon0())
    month_first=Date(today.y,today.m,1)
    def total_for(filt):
        return sum(a.duration_ns() for a in activities if filt.matches(a))
    today_total=total_for(Filter(project=project, from_date=today, to_date=today))
    week_total=total_for(Filter(project=project, from_date=week_first, to_date=today))
    month_total=total_for(Filter(project=project, from_date=month_first, to_date=today))
    running=[a for a in activities if a.is_running() and (project is None or a.project==project)]
    current=None
    if running:
        current=min(running, key=lambda a: a.start.fields())
    buf=[]
    buf.append(dim("\n ======="))
    if project is None:
        buf.append(italic(" Status for ")); buf.append(bold("ALL")); buf.append(italic(" projects "))
    else:
        buf.append(italic(" Status for project: ")); buf.append(bold(project))
    buf.append(dim(" ======= \n"))
    buf.append(dim_italic("\n  NOW: "))
    if current is not None:
        buf.append(bold_green(current.description))
        if project is None:
            buf.append(dim_italic(" on ")); buf.append(italic(current.project))
        buf.append(dim(" ...... "))
        buf.append(bold(duration_str(current.duration_ns())))
        buf.append(dim("\n\n"))
    else:
        buf.append(bold(" NO Activity\n\n"))
    labels=[(" Today......................... ",today_total),(" Current week.................. ",week_total),(" Current month................. ",month_total)]
    for lab,tot in labels:
        buf.append(italic(" ")); buf.append(dim_italic(lab)); buf.append(bold(duration_str(tot))); buf.append(italic("\n"))
    buf.append("\n")
    out("".join(buf))

def cmd_edit(path, vals):
    editor=vals.get("editor")
    if editor is None:
        raise AppError("editor command is missing")
    # Flush Python buffers before handing the terminal to the child.
    try: sys.stdout.buffer.flush(); sys.stderr.buffer.flush()
    except Exception: pass
    try:
        subprocess.call([editor, path])
    except OSError as e:
        raise AppError(io_error_str(e))
