class ParseState:
    def __init__(self,spec,top=False):
        self.spec=spec; self.top=top
        self.values={}; self.explicit=set(); self.occurrences={}
        self.no_value=[]  # arg ids in order
        self.final_pending=None
        self.first_duplicate=None
        self.used_optional=set()
        self.positional_present=set()
    def record(self,arg):
        self.explicit.add(arg.id)
        self.occurrences[arg.id]=self.occurrences.get(arg.id,0)+1
        if self.occurrences[arg.id]==2 and self.first_duplicate is None:
            self.first_duplicate=arg.id
        if (not arg.required) and (not arg.positional) and arg.id not in ("help","version"):
            self.used_optional.add(arg.id)
    def set_value(self,arg,value):
        self.values[arg.id]=value
        if arg.id in self.no_value: self.no_value.remove(arg.id)
    def set_no_value(self,arg,final=False):
        if arg.no_value_uses_default:
            self.values[arg.id]=arg.default
            return
        self.values[arg.id]=None
        if arg.id not in self.no_value: self.no_value.append(arg.id)
        if final: self.final_pending=arg.id
    def resolve(self):
        vals={}
        for a in self.spec.all_args(self.top):
            if a.id in self.values and self.values[a.id] is not None:
                vals[a.id]=self.values[a.id]
            elif a.env and a.env in os.environ:
                vals[a.id]=os.environ[a.env]
            elif a.default is not None:
                vals[a.id]=a.default
            elif a.is_flag:
                vals[a.id]=False
            else:
                vals[a.id]=None
        for a in self.spec.positionals:
            if a.id in self.values and self.values[a.id] is not None:
                vals[a.id]=self.values[a.id]
            elif a.default is not None:
                vals[a.id]=a.default
            else:
                vals[a.id]=None
        return vals

def _is_new_arg(tok):
    return len(tok)>=2 and tok[0]=="-"

def _find_conflict(state):
    present=[i for i in state.explicit if i in CONFLICT_RANK]
    if len(present)<2: return None
    # X = highest-ranked present argument that conflicts with another.
    present_sorted=sorted(present, key=lambda i: -CONFLICT_RANK[i])
    for x in present_sorted:
        peers=[y for y in present if y!=x and frozenset((x,y)) in CONFLICT_SET]
        if peers:
            # Reference choice among several peers is non-deterministic;
            # pick the lowest-ranked peer.
            y=sorted(peers, key=lambda i: CONFLICT_RANK[i])[0]
            return (x,y)
    return None

def validate_state(state, check_required=True):
    spec=state.spec
    if check_required:
        missing=[a for a in spec.args if a.required and a.id not in state.explicit]
        if missing:
            msg="error: The following required arguments were not provided:"
            for a in missing: msg+=f"\n    {a.display()}"
            raise clap_error(msg, smart_usage(spec, state.used_optional, state.top))
    if state.final_pending is not None:
        fid=state.final_pending
        amap={a.id:a for a in spec.all_args(state.top)}
        a=amap[fid]
        if state.occurrences.get(fid,0)>1:
            raise clap_error(f"error: The argument '{a.display()}' was provided more than once, but cannot be used multiple times", smart_usage(spec,state.used_optional,state.top))
        raise clap_error(f"error: The argument '{a.display()}' requires a value but none was supplied", smart_usage(spec,state.used_optional,state.top))
    conf=_find_conflict(state)
    if conf:
        amap={a.id:a for a in spec.all_args(state.top)}
        x=amap[conf[0]]; y=amap[conf[1]]
        raise clap_error(f"error: The argument '{x.display()}' cannot be used with '{y.display()}'", smart_usage(spec,state.used_optional,state.top))
    if state.first_duplicate is not None:
        amap={a.id:a for a in spec.all_args(state.top)}
        a=amap[state.first_duplicate]
        raise clap_error(f"error: The argument '{a.display()}' was provided more than once, but cannot be used multiple times", smart_usage(spec,state.used_optional,state.top))
    if state.no_value:
        amap={a.id:a for a in spec.all_args(state.top)}
        a=amap[state.no_value[0]]
        raise clap_error(f"error: The argument '{a.display()}' requires a value but none was supplied", smart_usage(spec,state.used_optional,state.top))

def _suggest_long(name, spec, top=False):
    candidates=[]; cmap={}
    for a in spec.all_args(top):
        if a.long:
            candidates.append(a.long); cmap[a.long]=a
    cand=did_you_mean(name,candidates)
    return cmap.get(cand) if cand else None

def parse_subcommand_tokens(spec, tokens):
    state=ParseState(spec, top=False)
    by_long=spec.by_long(False); by_short=spec.by_short(False)
    i=0; after_dd=False; pos_idx=0
    while i<len(tokens):
        tok=tokens[i]
        if not after_dd and tok=="--":
            after_dd=True; i+=1; continue
        if not after_dd and tok.startswith("--") and len(tok)>2:
            body=tok.lstrip("-")
            if "=" in body:
                name,attached=body.split("=",1)
            else:
                name,attached=body,None
            arg=by_long.get(name)
            if arg is None:
                sugg=_suggest_long(name,spec,False)
                unknown_arg_error("--"+name, spec, state.used_optional, False, sugg)
            if arg.id=="help":
                raise ClapExit(sub_help(spec.name),0,False)
            state.record(arg)
            if arg.is_flag:
                state.set_value(arg,True); i+=1
            else:
                if attached is not None:
                    state.set_value(arg,attached); i+=1
                elif i+1<len(tokens) and not _is_new_arg(tokens[i+1]):
                    state.set_value(arg,tokens[i+1]); i+=2
                else:
                    state.set_no_value(arg, final=(i==len(tokens)-1)); i+=1
            continue
        if not after_dd and tok.startswith("-") and len(tok)>1:
            chars=tok[1:]; j=0; consumed_next=False
            while j<len(chars):
                ch=chars[j]
                arg=by_short.get(ch)
                if arg is None:
                    unknown_arg_error("-"+ch, spec, state.used_optional, False, None)
                if arg.id=="help":
                    raise ClapExit(sub_help(spec.name),0,False)
                state.record(arg)
                if arg.is_flag:
                    state.set_value(arg,True); j+=1; continue
                rest=chars[j+1:]
                if rest!="":
                    val=rest[1:] if rest.startswith("=") else rest
                    state.set_value(arg,val); j=len(chars); break
                if i+1<len(tokens) and not _is_new_arg(tokens[i+1]):
                    state.set_value(arg,tokens[i+1]); consumed_next=True
                else:
                    state.set_no_value(arg, final=(i==len(tokens)-1))
                j+=1; break
            i+=2 if consumed_next else 1
            continue
        # Positional
        if pos_idx<len(spec.positionals):
            parg=spec.positionals[pos_idx]
            state.record(parg)
            # record() doesn't count positionals as used_optional (guarded)
            state.values[parg.id]=tok; state.positional_present.add(parg.id); pos_idx+=1; i+=1
        else:
            unknown_arg_error(tok, spec, state.used_optional, False, None)
    validate_state(state, check_required=True)
    return state

def parse_top_tokens(tokens):
    """Returns (state, subcommand_name, remaining_tokens)."""
