failures=[]; total=0
def run_one(exe,args,content,env_extra=None,path_suffix=""):
    # content: bytes or None for missing file. args may contain "{F}" placeholder replaced with filepath.
    d="/tmp/dt_ref" if exe==REF else "/tmp/dt_mine"
