        open(filepath,"wb").write(content)
    real_args=[]
    use_env_file=False
    for a in args:
        if a=="{F}":
            real_args.append(filepath)
        elif a=="{ENVF}":
            use_env_file=True
        else:
            real_args.append(a.replace("{DIR}",d))
    env=os.environ.copy(); env.pop("BARTIB_FILE",None); env.pop("EDITOR",None)
    if use_env_file: env["BARTIB_FILE"]=filepath
    if env_extra:
        for k,v in env_extra.items():
            if v is None: env.pop(k,None)
            else: env[k]=v.replace("{F}",filepath).replace("{DIR}",d) if isinstance(v,str) else v
    r=subprocess.run([exe]+real_args,capture_output=True,env=env)
    # Normalize filepath/dir differences in outputs
    def norm(b):
        return b.replace(d.encode(),b"{DIR}")
    file_after=None
    if os.path.exists(filepath):
        try: file_after=open(filepath,"rb").read()
        except Exception as e: file_after=f"<err {e}>".encode()
    return (r.returncode, norm(r.stdout), norm(r.stderr), file_after)

